import assert from 'node:assert/strict';
import { test } from 'node:test';

import { starBarrel } from './api-barrel.mjs';

const GENERATED = `/* eslint-disable */
/* Code generated by ng-openapi-gen DO NOT EDIT. */

export { ApiConfiguration } from './api-configuration';
export { provideApiConfiguration } from './api-configuration';
export type { StrictHttpResponse } from './strict-http-response';
export { Api } from './api';

export type { Me } from './models/me';
export type { Me$Params as Me$Params } from './fn/me/me';
export { me as me } from './fn/me/me';
`;

test('réexportations nommées → une réexportation « étoile » par module, dans l’ordre', () => {
  const lines = starBarrel(GENERATED)
    .split('\n')
    .filter((line) => line.startsWith('export'));
  assert.deepEqual(lines, [
    "export * from './api-configuration';",
    "export * from './strict-http-response';",
    "export * from './api';",
    "export * from './models/me';",
    "export * from './fn/me/me';",
  ]);
});

test('idempotent : un index déjà réécrit reste identique', () => {
  const once = starBarrel(GENERATED);
  assert.equal(starBarrel(once), once);
});

test('ligne inconnue ou index vide : refus, jamais de réécriture partielle', () => {
  assert.throws(() => starBarrel(`${GENERATED}const x = 1;\n`), /ligne inattendue/);
  assert.throws(() => starBarrel('/* vide */\n'), /aucune réexportation/);
});
